    internal static bool IsWide(int value) => Contains(WideRanges, value);
    internal static bool IsAmbiguous(int value) => Contains(AmbiguousRanges, value);
    internal static bool IsEmojiPresentation(int value) => Contains(EmojiPresentationRanges, value);
    private static bool Contains(int[] ranges, int value)
    {
        int low = 0, high = ranges.Length / 2 - 1;
        while (low <= high)
        {
            int middle = low + ((high - low) / 2), offset = middle * 2;
            if (value < ranges[offset]) high = middle - 1;
            else if (value > ranges[offset + 1]) low = middle + 1;
            else return true;
        }
        return false;
    }
